import { execSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

// Stamps a unique id into the build output so every deploy is detectable by
// both the running app (/version.json) and the service worker (/cache-version.json
// plus the worker's own bytes). Previously these were committed by hand and
// forgotten, so deployed clients kept running the old cached code.
//
// The id itself is generated by the version plugin in vite.config.ts, which
// also injects it into the bundle as __BUILD_ID__. It is read back from
// dist/version.json here so the worker's cache name and the app's own build id
// are the same value: if they drifted apart, a client could not tell whether
// the build it is running matches the cache the worker installed.

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'dist');

// The timestamp (base36) guarantees a new id even when the same commit is
// rebuilt, which is what forces the refresh on every deploy.
function gitShortSha() {
  try {
    return execSync('git rev-parse --short HEAD', { cwd: root, stdio: ['ignore', 'pipe', 'ignore'] })
      .toString()
      .trim();
  } catch {
    return 'nogit';
  }
}

function readBuildId() {
  try {
    const raw = JSON.parse(readFileSync(join(dist, 'version.json'), 'utf8'));
    if (raw && typeof raw.v === 'string' && raw.v) return raw.v;
  } catch {
    /* fall through */
  }
  // The plugin should always have written it. This is the safety net for a
  // build that skipped the plugin (and for a hand-run script).
  return `${gitShortSha()}-${Date.now().toString(36)}`;
}

const buildId = readBuildId();
const payload = `${JSON.stringify({ v: buildId })}\n`;

writeFileSync(join(dist, 'version.json'), payload);
writeFileSync(join(dist, 'cache-version.json'), payload);

// Rewriting sw.js with a new id changes its bytes, which is the only thing that
// makes a browser install the updated worker; otherwise a byte-identical sw.js
// is ignored forever and activate() never runs to purge the old caches.
//
// The worker also gets the manifest of every Vite-hashed JS/CSS chunk prepended,
// so it can precache the whole app at install. That keeps update swaps fully
// local — no network wait during the reload, so the swap reads as a smooth
// transition instead of a white shutter on a phone.
const swPath = join(dist, 'sw.js');
if (existsSync(swPath)) {
  const sw = readFileSync(swPath, 'utf8');
  if (!sw.includes('__BUILD_VERSION__')) {
    throw new Error('dist/sw.js has no __BUILD_VERSION__ placeholder to replace');
  }
  const stamped = sw.replaceAll('__BUILD_VERSION__', buildId);

  const indexPath = join(dist, 'index.html');
  let assets = [];
  try {
    const html = readFileSync(indexPath, 'utf8');
    assets = [...html.matchAll(/(?:src|href)="(\/assets\/[^"]+\.(?:js|css))"/g)].map(m => m[1]);
  } catch {
    throw new Error('dist/index.html is missing — run vite build first');
  }

  // Also precache every code-split chunk. The index.html only references the
  // entry files, so without this a lazily-loaded route would fail to open while
  // offline (which previously triggered a reload loop that ended on the
  // browser's native offline page).
  try {
    const chunks = readdirSync(join(dist, 'assets'))
      .filter(name => name.endsWith('.js') || name.endsWith('.css'))
      .map(name => `/assets/${name}`);
    assets = [...new Set([...assets, ...chunks])];
  } catch {
    /* no assets dir — entry-only precache */
  }

  const manifestHeader = `/* asset-manifest */ self.__BUILD_ASSETS__ = ${JSON.stringify(assets)};\n`;
  writeFileSync(swPath, manifestHeader + stamped);
  console.log(`[version] stamped build ${buildId} with ${assets.length} assets`);
} else {
  throw new Error('dist/sw.js is missing — run vite build first');
}

// The iOS launch images get the build id in their file name.
//
// iOS caches the apple-touch-startup-image it shows on a cold launch of an
// installed PWA, and it keys that cache by URL. With a stable URL there is
// nothing to make it look again, so a new splash only ever reached a customer
// who removed and reinstalled the app. Putting the build id in the name gives
// every deploy a new URL, which the cache cannot already hold.
//
// The files are renamed rather than copied, so the deploy costs no extra
// bytes, and the plain names in public/ stay the single source of truth.
const splashDir = join(dist, 'splash');
if (existsSync(splashDir)) {
  const indexPath = join(dist, 'index.html');
  let html = readFileSync(indexPath, 'utf8');
  let renamed = 0;
  for (const file of readdirSync(splashDir)) {
    if (!/^apple-splash-\d+-\d+\.png$/.test(file)) continue;
    const versioned = file.replace(/\.png$/, `.${buildId}.png`);
    renameSync(join(splashDir, file), join(splashDir, versioned));
    html = html.split(`/${file}"`).join(`/${versioned}"`);
    renamed++;
  }
  if (renamed) {
    writeFileSync(indexPath, html);
    console.log(`[version] versioned ${renamed} iOS launch images`);
  }
}
